package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.*;import dev.redstoneengineering.physics.*;import net.minecraft.core.*;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.util.RandomSource;import net.minecraft.world.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.block.Block;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Pressure accumulator. Charges toward line pressure with finite rate and slowly leaks when not replenished. */
public class AirReservoirBlock extends Block{public AirReservoirBlock(Properties p){super(p);}@Override public MapCodec<AirReservoirBlock> codec(){return RedstoneEngineering.AIR_RESERVOIR_CODEC.value();}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl){InformationRuntime.write(sl,"air_reservoir",p,0,0,true,100);sl.scheduleTick(p,this,10);PneumaticNetwork.recompute(sl,p);}}@Override protected void tick(BlockState s,ServerLevel l,BlockPos p,RandomSource r){int stored=InformationRuntime.value(l,"air_reservoir",p);int line=InformationRuntime.value(l,"pneumatic",p);int next=stored;if(line>stored)next=Math.min(line,stored+5);else if(stored>0)next=stored-1;InformationRuntime.write(l,"air_reservoir",p,Math.max(0,Math.min(100,next)),0,true,100);PneumaticNetwork.recompute(l,p);l.scheduleTick(p,this,10);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide){int stored=InformationRuntime.value(l,"air_reservoir",p);int line=InformationRuntime.value(l,"pneumatic",p);pl.displayClientMessage(Component.literal("Air reservoir stored="+stored+"/100 line="+line+"/100 chargeRate<=5/10t leak=1/10t"),true);}return InteractionResult.sidedSuccess(l.isClientSide);}}
